{"task": "customer-fk", "steps": [
  {"note": "Safety check before changing anything: abort the plan if any order already points at a missing customer. Read-only; nothing is deleted or rewritten.",
   "sql": "DO $$ DECLARE n bigint; BEGIN SELECT count(*) INTO n FROM orders o WHERE NOT EXISTS (SELECT 1 FROM customers c WHERE c.id = o.customer_id); IF n > 0 THEN RAISE EXCEPTION 'aborting: % orders reference missing customers', n; END IF; END $$;"},
  {"note": "Add the foreign key as NOT VALID (enforced for new and updated rows at once, no scan of the 10M existing rows). It needs a SHARE ROW EXCLUSIVE lock on orders for an instant, which briefly blocks INSERTs (reads are not blocked). lock_timeout 300ms keeps any queued INSERT far below the app's 2s statement timeout; on timeout it backs off and retries. Skipped if an orders->customers foreign key already exists.",
   "sql": "DO $$ DECLARE i int; BEGIN IF EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid = 'public.orders'::regclass AND confrelid = 'public.customers'::regclass AND contype = 'f') THEN RAISE NOTICE 'foreign key already present, skipping'; RETURN; END IF; PERFORM set_config('lock_timeout', '300ms', true); FOR i IN 1..60 LOOP BEGIN ALTER TABLE public.orders ADD CONSTRAINT orders_customer_id_fkey FOREIGN KEY (customer_id) REFERENCES public.customers (id) NOT VALID; RETURN; EXCEPTION WHEN lock_not_available THEN RAISE NOTICE 'attempt % could not get the lock, retrying', i; PERFORM pg_sleep(1); END; END LOOP; RAISE EXCEPTION 'could not add the foreign key: lock not obtained after 60 attempts'; END $$;"},
  {"note": "Validate the existing rows in its own transaction. VALIDATE CONSTRAINT only takes SHARE UPDATE EXCLUSIVE on orders and ROW SHARE on customers, so reads and inserts keep running during the full-table check. Parallel workers are turned off for this session to limit the CPU/IO hit on live traffic. Fails (changing nothing) if a violating row were found.",
   "sql": "SET max_parallel_workers_per_gather = 0; SET statement_timeout = 0; SET lock_timeout = 0; ALTER TABLE public.orders VALIDATE CONSTRAINT orders_customer_id_fkey;"},
  {"note": "Confirm the foreign key exists and is validated; fail the plan otherwise.",
   "sql": "DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid = 'public.orders'::regclass AND confrelid = 'public.customers'::regclass AND contype = 'f' AND convalidated) THEN RAISE EXCEPTION 'foreign key orders.customer_id -> customers.id is missing or not validated'; END IF; END $$;"}
]}
